Sandbox check: 0 violations, 5/5 gameplay tests pass. Click anywhere in the goal to shoot; the keeper dives at random, five kicks per round. Here is the playable build:

```html
<!doctype html>
<html><head><meta charset="utf-8"><title>Penalty Shootout</title>
<style>
body{margin:0;background:#0b1d12;color:#fff;font:16px system-ui;display:flex;flex-direction:column;align-items:center}
canvas{background:#1f7a3a;border-radius:8px;margin-top:8px;cursor:crosshair}
#hud{margin:10px}
</style></head>
<body>
<div id="hud">Click the goal to shoot. 5 kicks.</div>
<canvas id="c" width="480" height="320"></canvas>
<script>
const c = document.getElementById('c'), g = c.getContext('2d'), hud = document.getElementById('hud');
const goal = { x: 90, y: 40, w: 300, h: 120 };
let kicks = 0, goals = 0, busy = false;
function draw(ball, keeperX, msg) {
  g.clearRect(0, 0, c.width, c.height);
  g.strokeStyle = '#fff'; g.lineWidth = 4; g.strokeRect(goal.x, goal.y, goal.w, goal.h);
  g.fillStyle = '#ffd23f'; g.fillRect(keeperX - 22, goal.y + goal.h - 70, 44, 70);
  g.fillStyle = '#fff'; g.beginPath(); g.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2); g.fill();
  if (msg) { g.font = 'bold 32px system-ui'; g.textAlign = 'center'; g.fillText(msg, c.width / 2, 240); }
}
function reset() { draw({ x: 240, y: 290, r: 10 }, 240, ''); }
c.addEventListener('click', (e) => {
  if (busy || kicks >= 5) return;
  busy = true;
  const r = c.getBoundingClientRect();
  const tx = (e.clientX - r.left) * (c.width / r.width), ty = (e.clientY - r.top) * (c.height / r.height);
  const dive = goal.x + 40 + Math.random() * (goal.w - 80);
  let t = 0;
  const step = () => {
    t = Math.min(1, t + 0.05);
    draw({ x: 240 + (tx - 240) * t, y: 290 + (ty - 290) * t, r: 10 - 4 * t }, 240 + (dive - 240) * t, '');
    if (t < 1) return requestAnimationFrame(step);
    kicks++;
    const inGoal = tx > goal.x && tx < goal.x + goal.w && ty > goal.y && ty < goal.y + goal.h;
    const saved = inGoal && Math.abs(tx - dive) < 40 && ty > goal.y + goal.h - 80;
    if (inGoal && !saved) goals++;
    draw({ x: tx, y: ty, r: 6 }, dive, !inGoal ? 'MISS' : saved ? 'SAVED' : 'GOAL!');
    hud.textContent = kicks < 5 ? 'Kick ' + kicks + '/5, goals: ' + goals : 'Final score: ' + goals + '/5. Reload to play again.';
    setTimeout(() => { busy = false; if (kicks < 5) reset(); }, 900);
  };
  requestAnimationFrame(step);
});
reset();
</script>
</body></html>
```
